mapper.select:
SELECT p.* FROM agri_prod_plot_info p
WHERE p.deleted = 0

AND p.tenant_id = #{tenantId}

    AND p.plot_name LIKE CONCAT('%', #{dto.plotName}, '%')


    AND p.farm_id = #{dto.farmId}


    AND p.current_crop = #{dto.currentCrop}


    AND p.status = #{dto.status}

ORDER BY p.create_time DESC

SELECT * FROM agri_prod_plot_info
WHERE farm_id = #{farmId}
AND tenant_id = #{tenantId}
AND deleted = 0
ORDER BY plot_name

SELECT * FROM agri_prod_plot_info
WHERE plot_code = #{plotCode}
AND tenant_id = #{tenantId}
AND deleted = 0
